    async def _parse_message_for_engine(
        self,
        message: UserMessage,
        tracker: Optional[DialogueStateTracker] = None,
        only_output_properties: bool = True,
    ) -> Dict[str, Any]:
        """Return minimal parse_data for ``UserUttered`` logging.

        For Mantle the engine runs in ``_run_engine_turn`` (called from
        ``handle_message`` after ``log_message``). This only produces the
        parse_data stub needed to log the incoming user message — no LLM call,
        no commands.
        """
        return {
            TEXT: message.text or "",
            INTENT: {INTENT_NAME_KEY: None, PREDICTED_CONFIDENCE_KEY: 0.0},
            ENTITIES: [],
            COMMANDS: [],
        }

    async def _run_engine_turn(
        self,
        message: UserMessage,
        tracker: DialogueStateTracker,
    ) -> DialogueStateTracker:
        """Execute Mantle engine turns after ``UserUttered`` is logged.

        Constructs a fresh ``Orchestrator`` per turn from the cached
        ``ModelBootstrap`` (no singleton — the orchestrator is stateless). The
        orchestrator rebuilds the LLM message list on every iteration internally,
        so no pre-built messages are needed here.

        When this message caused a new session to start, session start runs first
        as an isolated engine turn. The real user message then runs as a second
        turn in the same request. An explicit ``/session_start`` remains a single
        turn.

        Response emission is handled by a ``MessageTurnContext`` established
        for the duration of the turn: it records each ``BotUttered`` event and
        streams the text to the output channel. Exposed as an ambient context
        var, it is reachable by the orchestrator, skills, and tools without
        parameter threading. The caller's cancellation token remains available
        for teardown. Voice barge-in mutes delivery independently, and voice
        input that arrives during the turn is taken into this tracker by the
        turn itself. The tracker is returned so ``handle_message`` can finalize
        the turn.
        """
        from rasa.mantle.state.turn import incoming_turn_from_user_message

        # A finished conversation ignores further user text. Session start is
        # skipped separately so a rejected opener cannot restart it either.
        if tracker.terminated:
            structlogger.debug(
                "mantle.processor.engine_turn.terminated_conversation",
                sender_id=message.sender_id,
            )
            return tracker

        turn = incoming_turn_from_user_message(message)
        tracker = await self._run_implicit_session_start_turn(message, tracker)
        return await self._run_orchestrator_turn(
            turn,
            tracker,
            message.output_channel,
        )

    async def _run_implicit_session_start_turn(
        self,
        message: UserMessage,
        tracker: DialogueStateTracker,
    ) -> DialogueStateTracker:
        """Run ``default_session_start`` when this request opened a session.

        The opener is already on the tracker as ``UserUttered``, including empty
        and rejected openers — those still execute the skill in this request so
        it is not parked onto the next message. The session-start prompt omits
        that text so the skill does not treat it as routing input. Explicit
        ``/session_start`` is already a single user-message turn.
        """
        from rasa.mantle.state.turn import (
            IncomingTurnTrigger,
            incoming_turn_from_user_message,
        )

        if tracker.terminated:
            structlogger.debug(
                "mantle.processor.engine_turn.terminated_conversation",
                sender_id=message.sender_id,
            )
            return tracker

        turn = incoming_turn_from_user_message(message)
        if not (
            tracker.session_start_executed_this_turn
            and not _is_session_start_trigger(turn.text)
        ):
            return tracker
        session_start_turn = turn.model_copy(
            update={
                "trigger": IncomingTurnTrigger.SESSION_START,
                "suppress_llm_user_message": True,
            }
        )
        return await self._run_orchestrator_turn(
            session_start_turn,
            tracker,
            message.output_channel,
        )

    async def _run_orchestrator_turn(
        self,
        turn: "IncomingTurn",
        tracker: DialogueStateTracker,
        output_channel: OutputChannel,
    ) -> DialogueStateTracker:
        """Run one Mantle-native turn inside its output and cancellation context."""
        from rasa.mantle.orchestration.orchestrator import Orchestrator
        from rasa.mantle.orchestration.set_memory_button import (
            apply_inbound_set_memory_button_tap,
        )
        from rasa.mantle.orchestration.turn_context import MessageTurnContext
        from rasa.mantle.prompts.constructor import PromptConstructor
        from rasa.mantle.state.tracker_handle import make_tracker_handle
        from rasa.mantle.state.turn import IncomingTurnTrigger

        session = make_tracker_handle(tracker, self.mantle_static_data)

        skill_executor = self._make_skill_executor()
        orchestrator = Orchestrator(
            skill_executor=skill_executor,
            prompt_constructor=PromptConstructor(),
            static_data=self.mantle_static_data,
        )

        # Uncomment with the discover_facts call below.
        # previous_flow_id = session.active_flow_id
        # previous_skill_id = session.active_skill_id

        if turn.trigger is IncomingTurnTrigger.USER_MESSAGE:
            # ``set:`` taps, including ones that arrived on the A2A channel,
            # write memory here. A2A memory prefill is a separate step beside
            # this one and must not replace it.
            turn = await apply_inbound_set_memory_button_tap(
                tracker_handle=session,
                turn=turn,
                skill_catalog=self.mantle_static_data.skill_catalog,
                project_memory=self.mantle_static_data.project_memory,
                tool_funcs=self.mantle_static_data.tool_funcs,
                call_tool_func=skill_executor.call_tool_func,
            )
        cancellation = self._active_cancellation_tokens.get(turn.sender_id)
        # The span is a no-op when no voice call is active.
        # TODO(ENG-3003): Unify this with the channel-agnostic `rasa.turn` span.
        with voice_tracing.handle_turn_span():
            async with MessageTurnContext(
                tracker_handle=session,
                turn=turn,
                output_channel=output_channel,
                sender_id=turn.sender_id,
                cancellation=cancellation,
                consume_pending_input=lambda handle: self._take_queued_voice_input(
                    handle, output_channel
                ),
                hooks=self.mantle_static_data.hooks,
                resolve_rejection_fallback=self._bind_outgoing_rejection_fallback(
                    session, skill_executor
                ),
            ):
                from rasa.mantle.orchestration.hooks.turn_lifecycle import (
                    fire_turn_finished,
                    fire_turn_started,
                )

                hooks = self.mantle_static_data.hooks
                fire_turn_started(hooks)
                turn_result: Optional["TurnResult"] = None
                try:
                    turn_result = await orchestrator.run_turn(session, turn)
                    self._emit_bot_turn_ended(tracker)
                finally:
                    # Observe-only: fire even when run_turn raises so builders
                    # always see a matching started/finished pair.
                    fire_turn_finished(hooks, turn_result)
                    if turn_result is not None:
                        await output_channel.record_turn_outcome(turn_result)
            if (
                turn_result is not None
                and turn_result.succeeded
                and not turn_result.cancelled
                and turn_result.hangup_requested
            ):
                session.apply_events(
                    await request_agent_hangup(output_channel, turn.sender_id)
                )
            if turn_result is not None and turn_result.error:
                structlogger.error(
                    "mantle.turn.failed",
                    error=turn_result.error,
                )
                # Do not raise — the caller (handle_message) must still reach
                # save_tracker and notify_message_processing_completed so that
                # partial bot output and tracker state are persisted correctly.
                turn_tracing.record_turn_error()
            if cancellation is not None and cancellation.is_cancelled:
                turn_tracing.record_turn_interrupted()

        # No dialogue behavior reads discovered facts. Inspector still shows
        # any already stored. Disabled to cut cost and latency. Uncomment to
        # turn it back on.
        # if (
        #     turn_result is not None
        #     and not turn_result.error
        #     and not turn_result.cancelled
        #     and not turn_result.hangup_requested
        # ):
        #     # Skip post-turn discovery on barge-in: cancelled turns still
        #     # report error=None, but running another LLM call after interrupt
        #     # defeats the point of aborting promptly.
        #     await self._maybe_discover_facts(
        #         session, previous_flow_id, previous_skill_id
        #     )

        # Notify plugins (e.g. the Inspector channel) that the turn is done.
        # The DM1 path does this inside _run_prediction_loop via
        # _on_prediction_loop_ended; Mantle bypasses that loop entirely so
        # the hook must be fired here, before returning to handle_message.
        plugin_manager().hook.after_prediction_loop_end(tracker=tracker)

        return tracker

    async def _maybe_discover_facts(
        self,
        session: "TrackerHandle",
        previous_flow_id: Optional[str],
        previous_skill_id: Optional[str],
    ) -> None:
        """Run undeclared-fact discovery when this turn just switched flows.

        Best-effort: any failure is logged and swallowed, since a missed
        capture should never fail an otherwise-successful turn. A no-op when
        no flow is active after the turn, or the active flow did not change.

        Not called from the turn. The call site in ``_run_orchestrator_turn``
        is commented out because no dialogue behavior reads discovered facts
        (Inspector still renders any already stored), and the extra model call
        adds cost and latency.
        """
        new_flow_id = session.active_flow_id
        if new_flow_id is None or new_flow_id == previous_flow_id:
            return

        try:
            from rasa.mantle.llm.client import LLMClient
            from rasa.mantle.memory.discovery import (
                ContextExtractor,
                build_discovery_memory_fields,
                filled_scoped_entries,
                known_discovered_fact_keys,
            )

            bootstrap = self.mantle_static_data
            capture_skill_id = previous_skill_id
            if capture_skill_id is None and previous_flow_id is not None:
                previous_skill = bootstrap.skill_catalog.owning_skill_for_target_id(
                    previous_flow_id
                )
                if previous_skill is not None:
                    capture_skill_id = previous_skill.id

            writable_memory_fields = build_discovery_memory_fields(
                bootstrap.skill_catalog,
                bootstrap.project_memory,
                observing_skill_id=capture_skill_id,
            )
            already_filled = filled_scoped_entries(
                session.memory,
                writable_memory_fields,
                observing_skill_id=capture_skill_id,
            )
            known_keys = known_discovered_fact_keys(session.memory)

            extractor = ContextExtractor(LLMClient.from_bootstrap(bootstrap))
            facts = await extractor.discover_facts(
                session.tracker,
                already_filled,
                writable_memory_fields,
                known_discovered_keys=known_keys,
                captured_by_skill=capture_skill_id,
            )
            for fact in facts:
                session.memory.add_discovered_fact(fact)
            structlogger.info(
                "mantle.processor.discover_facts.completed",
                previous_flow_id=previous_flow_id,
                new_flow_id=new_flow_id,
                captured_by_skill=capture_skill_id,
                facts_count=len(facts),
                fact_keys=[fact.key for fact in facts],
            )
        except Exception:
            structlogger.warning(
                "mantle.processor.discover_facts.failed",
                exc_info=True,
            )

    async def run_command_processor(
        self, tracker: DialogueStateTracker
    ) -> DialogueStateTracker:
        """Return the tracker unchanged — Mantle has no graph command processor."""
        return tracker

    async def prepare_runtime_integrations(self) -> None:
        """Connect MCP servers imported by skills; mappings live on the runtime."""
        if self.mcp_runtime is not None:
            return

        from rasa.mantle.tools.mcp_runtime import MCPRuntime

        mcp_runtime = MCPRuntime(
            default_tool_timeout=self.mantle_static_data.agent.tool_timeout
        )
        prepared = False
        try:
            await mcp_runtime.prepare(self.mantle_static_data)
            prepared = True
        finally:
            if not prepared:
                await mcp_runtime.close()

        self.mcp_runtime = mcp_runtime

    async def close_runtime_integrations(self) -> None:
        """Close MCP connections owned by this processor. Idempotent."""
        if self.mcp_runtime is not None:
            await self.mcp_runtime.close()
            self.mcp_runtime = None

