    async def get_flows(self) -> "FlowsList":
        """Return an empty flows list — Mantle has no CALM v1 flows.

        The inspector consumes the native skill catalog
        (:meth:`inspector_data`) instead of a lossy v1 conversion. Callers
        reaching this method are on a v1-flow code path that should not run
        against the skill engine — the warning surfaces them so each one gets
        ported or removed as the Mantle implementation completes.
        """
        from rasa.shared.core.flows import FlowsList

        structlogger.warning(
            "mantle.processor.get_flows_called",
            event_info=(
                "get_flows() was called on the Mantle processor. The skill "
                "engine has no v1 flows; this call site should consume the "
                "skill catalog instead."
            ),
        )
        return FlowsList([])

    async def inspector_data(self) -> Dict[str, Any]:
        """Extend the base inspector payload with the serialized skill catalog.

        Declares ``engine="mantle"`` outright so the frontend knows it is in
        skill mode; the skills catalog is shipped as data, not as the engine
        signal.
        """
        from rasa.mantle.inspector import serialize_skill_catalog

        data = await super().inspector_data()
        data["engine"] = "mantle"
        data["skills"] = serialize_skill_catalog(self.mantle_static_data.skill_catalog)
        return data

    def inspector_skill_state(
        self, tracker: DialogueStateTracker
    ) -> Optional[Dict[str, Any]]:
        """Return per-tracker skill state for the development inspector.

        Best-effort: the inspector is a dev-tool overlay, so a failure here is
        logged and swallowed rather than allowed to break tracker streaming.
        Failures return an *empty* state (not ``None``): the frontend keeps the
        previous state when the key is absent, and honest-empty beats stale.
        """
        from rasa.mantle.inspector import build_skill_state, empty_skill_state
        from rasa.mantle.llm.call_log import llm_calls_for

        try:
            return build_skill_state(tracker, self.mantle_static_data)
        except Exception:
            structlogger.warning(
                "mantle.processor.inspector_skill_state_failed",
                sender_id=tracker.sender_id,
                exc_info=True,
            )
            # Honest-empty for derived state, but the ephemeral call log is
            # independent of the failed build — keep it visible.
            state = empty_skill_state()
            state["llm_calls"] = llm_calls_for(tracker.sender_id)
            return state

